-- GENERATED by scripts/build-content.mjs — challenge pack 2 (picture riddles, riddles, emoji movies, tech quick-fire, mini sudoku, Fruit Slash), part 3.
insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay,
  attempts, time_limit, hint, explanation, points, coins, status) values
('mission-riddle-1', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I''m tall when I''m young and short when I''m old.","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"I have a neck but no head, and I wear a cap.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"I have many teeth but I can''t bite.","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["CANDLE","ACANDLE"]},{"label":"Riddle 2 (Decoder)","accept":["BOTTLE","ABOTTLE"]},{"label":"Riddle 3 (Intel)","accept":["COMB","ACOMB","ZIP","ZIPPER"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'CANDLE: a candle | BOTTLE: a bottle | COMB: a comb', null, 25, 'published'),
('mission-riddle-2', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"What gets wetter the more it dries?","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"I have cities but no houses, forests but no trees, water but no fish.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What can you catch but never throw?","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["TOWEL","ATOWEL"]},{"label":"Riddle 2 (Decoder)","accept":["MAP","AMAP"]},{"label":"Riddle 3 (Intel)","accept":["COLD","ACOLD"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'TOWEL: a towel | MAP: a map | COLD: a cold', null, 25, 'published'),
('mission-riddle-3', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I have one eye but cannot see.","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"I speak without a mouth and hear without ears.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What goes up but never comes down?","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["NEEDLE","ANEEDLE"]},{"label":"Riddle 2 (Decoder)","accept":["ECHO","ANECHO"]},{"label":"Riddle 3 (Intel)","accept":["AGE","YOURAGE"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'NEEDLE: a needle | ECHO: an echo | AGE: your age', null, 25, 'published'),
('mission-riddle-4', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I have a head and a tail but no body.","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"The more of me there is, the less you see.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What has hands but can''t clap?","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["COIN","ACOIN"]},{"label":"Riddle 2 (Decoder)","accept":["DARKNESS","DARK","FOG"]},{"label":"Riddle 3 (Intel)","accept":["CLOCK","ACLOCK","WATCH"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'COIN: a coin | DARKNESS: darkness | CLOCK: a clock', null, 25, 'published')
on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category,
  difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts,
  relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint,
  explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status,
  version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts
                 then mission_templates.version + 1 else mission_templates.version end,
  updated_at = now();
